\begin{cases}
f(n)=cn, & n\in\mathbb N^+,\quad \text{if }0<\alpha<2,\\[4pt]
f(1)=c,\ f(2)=d \text{ arbitrary},\quad f(3)=c+d,\ \text{and}\ f(n)=c+f(n-1)\ (n\ge4),\quad \text{if }\alpha=2,\\[4pt]
f(1)=c,\ f(2)=d \text{ arbitrary},\quad f(n)=c+f(n-1)\ (n\ge3),\quad \text{if }\alpha>2.
\end{cases}

\text{If } \alpha=1,\ f(n)=cn.\ \text{If } \alpha\ne1,\ \text{let }N\in\mathbb Z^+ \text{ with }\alpha<N<\alpha+1;\ \text{then every solution is}
\begin{cases}
f(n)=a_n,&1\le n\le N,\ \text{arbitrary},\\[2mm]
f(n)=f(n_0)+\bigl(f(1)-f(n_0)\bigr)(n-n_0),&n>N,
\end{cases}
\text{ for some }n_0\le N.

\begin{cases}
f(n)=cn,\ \text{all }n\in\mathbb N^+,\ c\in\mathbb R, & 0<\alpha\le 1,\\[2mm]
f(n)=cn+h(n-1),\ \text{where }c\in\mathbb R\text{ and }h:\mathbb Z_{2(\alpha+1)}\to\mathbb R, & \alpha>1.
\end{cases}

\begin{cases}
f(n)=cn\quad(n\in\mathbb N^+), & 0<\alpha<1,\ c\in\mathbb R,\\[4pt]
f(n)=c d\left(\left\lfloor\frac{n-1}{d}\right\right\rfloor+1\right)+a_{((n-1)\bmod d)+1}, & \alpha\ge1,\ c,a_1,\dots,a_{d-1}\in\mathbb R,
\end{cases}

\begin{cases}
f(n)=cn,\ n\in\mathbb N^+,\ c\in\mathbb R, & \text{if } \sqrt2-1\le \alpha\le 1+\sqrt2,\\[4pt]
f(n)=c_{r}n \text{ on each residue class } r \pmod{q},\text{ with }c_r\in\mathbb R, & \text{if } \alpha<\sqrt2-1 \text{ or } \alpha>1+\sqrt2,
\end{cases}

\begin{cases}
f(n)=cn\ \text{for all }n\in\mathbb N^+, & \text{if }0<\alpha\le1,\text{ with arbitrary }c\in\mathbb R,\\[2mm]
f(n)=cn\ \text{for }n\in S(\alpha),\quad f(n)\text{ arbitrary for }n\notin S(\alpha), & \text{if }\alpha>1,
\end{cases}

\begin{cases}
f(n)=cn,\quad n\in\mathbb N^+,\ c\in\mathbb R, & \text{if }0<\alpha\le 1,\\[6pt]
f(n)=c_{r}+b\,n,\quad r\equiv n\pmod{\lfloor\alpha\rfloor+1},\ r=1,2,\dots,\lfloor\alpha\rfloor+1,\\
\text{where } b,c_1,\dots,c_{\lfloor\alpha\rfloor+1}\in\mathbb R \text{ are arbitrary}, & \text{if }\alpha>1.
\end{cases}

\begin{cases}
f(n)=c\,n\quad(n\in\mathbb N^+),\ c\in\mathbb R, & \alpha\ge 1,\\[1.2ex]
f(n)=c\,n+\displaystyle\sum_{i=0}^{N}\lambda_i\,A_i(n),\quad
N=\left\lfloor\frac1\alpha\right\rfloor,\ \lambda_i\in\mathbb R, & 0<\alpha<1,
\end{cases}

\begin{cases}
k=2^s t,\ t\ \text{odd},\ t\mid 3^{v_2(3k)+1}-1,\quad s\le v_2(3^{t+1}-1), & h=1,\\[4pt]
k=2^s t,\ t\ \text{odd},\ t\mid 3^{t+1}-1,\quad s\le r+v_2(3^{t+1}-1), & h=2^r\ (r\ge1).
\end{cases}

\begin{cases}
\{k\in\mathbb N:\ v_2(k)=r+1\}, & r\ge 1,\\[4pt]
\{k\in\mathbb N:\ v_2(k)\ge 1\}, & r=0.
\end{cases}

\left\{
q^r\prod_{j=0}^{\infty}2^{\min(j,r)}\,a_j
:\ q \text{ prime},\ (q-1)\mid 2^r,\ 0\le a_j\le q-2,\ a_j\in(\mathbb Z/q\mathbb Z)^\times
\right\}

\begin{cases}
\{2\}, & h=2^r\ge2,\\[2mm]
\{k\in\mathbb N:\ k\ne2^a\text{ for any }a\ge0\}, & h=1.
\end{cases}

\;
K(h)=\max_{\substack{m\ \mathrm{odd}>1}}
2^{\,v_2(m^h-1)-\max_i v_2(\varphi(p_i^{a_i}))},\quad
p_i^{a_i}\parallel m,
\]
and the required set is
\[
\boxed{\;
\left\{\,k\in\mathbb N:\ k\mid m^h-1,\ \frac{m^h-1}{k}\le K(h),\ \frac{m^h-1}{k}\ \text{a power of two}\ \text{and}\ \operatorname{odd}\!\left(\frac{m^h-1}{k}\right)\mid \operatorname{odd}(m^h-1)\ \right\}\;}
\]

d_n=\begin{cases}
n\,2^{\frac n2-1}+1, & n \text{ even},\\[4pt]
(n-1)2^{\frac{n-3}{2}}+1, & n \text{ odd}.
\end{cases}

\begin{cases}
f(n)=cn, & n\in\mathbb N^+,\quad c\in\mathbb R, && \alpha\le 1,\\[6pt]
f(n)=\begin{cases}
a, & n=1,\\
b, & n=2,\\
f(n-2)+b, & n\ge 3,
\end{cases}
\quad a,b\in\mathbb R, && 1<\alpha\le 2,\\[6pt]
f(n)=\begin{cases}
a, & n=1,\\
b, & n=2,\\
f(n-1)+a, & n\ge 3,
\end{cases}
\quad a,b\in\mathbb R, && \alpha>2.
\end{cases}

\begin{cases}
\text{all functions } f(n)=cn\ (c\in\mathbb R), & \exists\,r\in\mathbb N,\ r\ge2,\ r-1\le\alpha\le r;\\[4pt]
\text{only the zero function}, & \alpha\in(0,1)\ \text{or}\ \alpha\in\mathbb N\setminus\{1\}.
\end{cases}

\begin{cases}
\text{If }0<\alpha<\tfrac12,\text{ the functions are determined by arbitrary values }c_i=f(i),\ i=2,3,\dots,\lfloor\alpha\rfloor+2,\text{ and for every }n\ge 2 \text{ set }c_{\lfloor\alpha\rfloor+3}=\cdots,\text{ with }f(n)=cn\text{ on each component determined by the initial values.}\\[4pt]
\text{If }\alpha\ge\tfrac12,\text{ all solutions are }f(n)=cn\text{ for some }c\in\mathbb R.
\end{cases}

\begin{aligned}
(a)\quad & L=\{2m:m\in\mathbb N_{0},\ m\ge1\}=\{n\in\mathbb N_{0}: n\ \text{even},\ n\ge2\},\\
& E=\{0,1\}\cup\{2^j-1:j\ge1\}\cup\{2^j-2:j\ge2\},\\
& G=\mathbb N_{0}\setminus(L\cup E),\\[2mm]
(b)\quad & a_k=2^{k-1}-1\qquad(k\ge1),\quad a_0=0.
\end{aligned}

\begin{aligned}
L&=\left\{\,n=2^{m}+2^{m-1}(r+1)-1:\ m\ge1,\ r\ge0,\ r+1\text{ even}\,\right\},\\
E&=\left\{\,n=2^{m}+2^{m-1}(r+1)-1:\ m\ge1,\ r\ge0,\ r+1\text{ odd}\,\right\},\\
G&=\left\{\,n=2^{m}+2^{m-1}(r+1):\ m\ge0,\ r\ge0,\ r+1\text{ odd}\,\right\},\\
a_k&=
\begin{cases}
0,&k=0,\\
(k-1)2^{k-1},&k\ge1.
\end{cases}
\end{aligned}

\begin{aligned}
(a)\quad
&L=\{n\in\mathbb N_0:\ n>0,\ n\text{ is even}\}
   =\{n\ge1:\ n\equiv0,2\pmod4\},\\
&E=\{0\}\cup\{n\in\mathbb N_0:\ n\equiv1\pmod4\},\\
&G=\{n\in\mathbb N_0:\ n\equiv3\pmod4\}.\\[4pt]
(b)\quad
&a_k=
\begin{cases}
0, & k=0,\\[2pt]
(k-2)2^{k-1}+1, & k\ge1.
\end{cases}
\end{aligned}

\begin{aligned}
&\text{(a) } L=\{n\in\mathbb N_0:n\ge2,\ n\equiv0\pmod2\},\quad
E=\{0\}\cup\{n\in\mathbb N_0:n\equiv1\pmod4\},\\
&\qquad G=\{n\in\mathbb N_0:n\equiv3\pmod4\};\\[2mm]
&\text{(b) } a_0=0,\quad a_k=(k-2)2^{k-1}+1\ \ (k\ge1).
\end{aligned}

\begin{aligned}
E&=\{2^{k+1}-2:k\ge 0\},\\
G&=\{2k-1:k\ge 1\},\\
L&=\mathbb N_0\setminus\bigl(E\cup G\bigr),\\[2mm]
a_k&=2^{k+1}-2k-3\quad(k\ge0).
\end{aligned}

\,n=
\begin{cases}
3, & \text{if } m \text{ is a prime power},\\[2mm]
4, & \text{if } m \text{ has at least two distinct prime factors}.
